<?php $dir = __DIR__."/app"; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir)); $empty = 0; foreach($it as $f) { if($f->getExtension() == "php") { $c = file_get_contents($f->getPathname()); if(preg_match_all("/catch\s*\([^{]+\)\s*{\s*}/", $c, $matches)) { $empty += count($matches[0]); echo $f->getFilename()." has empty catch\n"; } } } echo "Total empty catch blocks: $empty\n";
